DROP VIEW "lldp_view";--> statement-breakpoint
CREATE VIEW "lldp_view" AS (select "lldp_neighbor"."id" as "id", "lldp_neighbor"."device_id" as "local_device_id", "local_device"."name" as "local_device_name", "local_device"."ipv4" as "local_device_ipv4", "lldp_neighbor"."interface_id" as "local_interface_id", "local_interface"."if_name" as "local_interface_name", "local_interface"."if_descr" as "local_interface_desc", "lldp_neighbor"."sys_name" as "neighbor_sys_name", "lldp_neighbor"."port_id" as "neighbor_port_id", "lldp_neighbor"."port_desc" as "neighbor_port_desc", "lldp_neighbor"."mgmt_address" as "neighbor_mgmt_address", "lldp_neighbor"."chassis_id" as "neighbor_chassis_id", "lldp_neighbor"."remote_device_id" as "remote_device_id", "remote_device"."name" as "remote_device_name", "remote_device"."ipv4" as "remote_device_ipv4", "lldp_neighbor"."remote_interface_id" as "remote_interface_id", "remote_interface"."if_name" as "remote_interface_name", "lldp_neighbor"."updated_at" as "updated_at" from "lldp_neighbor" left join "device" "local_device" on "lldp_neighbor"."device_id" = "local_device"."id" left join "interface" "local_interface" on "lldp_neighbor"."interface_id" = "local_interface"."id" left join "device" "remote_device" on "lldp_neighbor"."remote_device_id" = "remote_device"."id" left join "interface" "remote_interface" on "lldp_neighbor"."remote_interface_id" = "remote_interface"."id");